export default {
  name: "UserGuide",
  props: {
    show: {
      type: Boolean,
      default: false,
      required: true
    }
  },
  data() {
    return {
      showGuide: false
    };
  },
  watch: {
    show(val) {
      this.showGuide = val;
    },
    showGuide(newVal) {
      this.$emit("update:show", newVal);
    }
  },
  mounted() {
    this.showGuide = this.show;
  }
};